for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
    rel=f'sources/{tree}/fr/232.tex'
    def r(a,b,line,why,kind='reading',count=1):
        replace(rel,a,b,layer,'232-147',line,'2.2-2.5',
                'Scan leaf 6 at 400 dpi, all three enlarged bands, and separate alphabet/final-reference crops: '+why,kind=kind,count=count)
    r(r'\mathcal F',r'\mathfrak F','pullback functor','F is handwritten Gothic, with curled top and lower hooked stem.',count=2)
    r(r'\mathcal G',r'\mathfrak G','essential-image description','G is handwritten Gothic, with the same ornamental two-bowl construction.',count=4)
    r(r'\longmapsto',r'\rightsquigarrow','pullback assignment','The print has a wavy assignment arrow without a mapsto bar.')
    r(r'\longrightarrow',r'\to','seven arrows','All seven arrows are short.',count=7)
    r(r'\xrightarrow{\sim}',r'\overset{\sim}{\to}','four isomorphisms','The tilde is over a short right arrow.',count=4)
    r(r'\simeq',r'\overset{\sim}{\to}','last Picard comparison','The final comparison also has a short right arrow under its tilde.')
    r(r"\operatorname{Pic}'_{X/S}",r"\mathop{\text{\uwave{Pic}}}\nolimits'_{X/S}",'2.3 source','The restricted functor is wavy underlined.')
    r(r'\operatorname{Pic}_{X/S}',r'\mathop{\text{\uwave{Pic}}}\nolimits_{X/S}','2.3 target','The full functor is wavy underlined.')
    r('(Donc,\n','(Donc\n','2.3 parenthesis','There is no comma after Donc.')
    r('i.e.','i. e.','2.4','The abbreviation has spaced initials.')
    r(r'\result{REMARQUE}{2.5}',r'\result{\uline{Remarque}}{2.5}','2.5 heading','Only Remarque, in mixed case, is straight underlined.')
    r('sur $X$ ; appelons','sur $X$, appelons','2.5 definition','The punctuation is a comma, not a semicolon.')
    r('$g$-rigidification de',r'$g$-\uline{rigidification} de','first rigidification term','Only the word rigidification is underlined; the prefix g-hyphen is outside it.')
    r('\\emph{Module\ninversible $g$-rigidifié}', '\\uline{Module\ninversible} $g$-\\uline{rigidifié}','rigidified-module definition','The words Module inversible and rigidifié are straight underlined; the g-hyphen prefix is not.')
    note=list(footnotes(page_text(rel,147)[0]))
    assert len(note)==1
    r(r'\footnote{'+note[0][2]+'}','', 'editorial footnote after rigidified classes','No footnote or note marker occurs in the print. The explanation belongs in the audit record.','structure')
    r('isomorphisme près, de Modules inversibles $g$-rigidifiés sur $X$', 'isomorphisme près, de Modules inversibles $g$-rigidifiés sur $S$', '2.5 classification sentence','The print says sur S at this place.')
    r('prouver 2.2(ii).','prouver 2.2, (ii).','2.5 parenthetical reference','The print has a comma and a space between 2.2 and (ii).')
    if tree=='fr':
        r('isomorphisme près, de Modules inversibles $g$-rigidifiés sur $S$', 'isomorphisme près, de Modules inversibles $g$-rigidifiés sur $X$', '2.5 classification sentence','The objects being rigidified are invertible modules on X, with trivialization of their pullback along g:S to X. Modules on S would not have the stated g-pullback.','misprint of the original')
        r(r'\result{COROLLAIRE}{2.3} Sous les conditions de 2.2,',r'\result{COROLLAIRE}{2.3} Sous les conditions de 2.2, supposées vérifiées après tout changement de base,','2.3 hypotheses','The conclusion concerns functors on every S-scheme, so the direct-image equality must hold after every base change. Counterexample without this condition: S=Spec R[t], X=P1_S minus the degree-two point x^2+y^2=0 of the fibre t=0. Hartogs on the regular surface gives f_*O_X=O_S and X has a real section, but the closed fibre U has Pic(U)=Z/2 and its complex base change has Pic=0. The nonzero class of Pic-prime(U/R) is therefore killed in the associated fpqc sheaf.','misprint of the original')
    upright_page(rel,layer,'232-147')
event('232-2.2','independent re-proof','For finite locally free F on S, the unit F to f_*f^*F is an isomorphism, checked on trivializing opens from f_*O_X=O_S. Adjunction then makes pullback fully faithful and characterizes its essential image by the counit and local freeness of f_*G. For a Pic-prime class becoming zero after an fpqc cover, represent it Zariski locally by a line bundle L. Flat base change for quasi-compact separated f identifies the pullback of f_*L with f-prime_*L-prime. Local freeness and the counit isomorphism descend faithfully flat, so L is pulled back from the base and its relative class is zero. With a local section, normalize L by the inverse pullback of its restriction to that section. Rigidified automorphisms are trivial; matching relative classes therefore yield unique rigidified isomorphisms on overlaps, automatically satisfying the cocycle identity. Effective descent of line bundles gives (ii). Flat base change and effective module descent are the stated background inputs.','232, pp. 146-147, proposition and proof')
event('232-2.3-printed','refuted, with the refined statement id 232-2.3-universal','The claim is stated for Picard functors on all S-schemes, but the hypotheses of 2.2 only concern the original base. Let S=Spec R[t] and delete from P1_S the closed degree-two point t=0, x^2+y^2=0. The removed set has codimension two in a regular surface, so normal extension of regular functions gives f_*O_X=O_S on every base open. The morphism is quasi-compact separated and has a section. On the closed fibre U=P1_R minus that point, the divisor-class sequence gives Pic(U)=Z/2, whereas U_C=P1_C minus two points has Pic=0. Since the base is a field, Pic-prime(U/R)=Pic(U); its nonzero class vanishes after the fpqc extension C/R and hence in the associated sheaf. Thus even injectivity fails at this test scheme.','232, p. 147, corollary 2.3')
event('232-2.3-universal','targeted proof check','Assume the hypotheses of 2.2 after every base change. Applying 2.2(i) to each test scheme makes the restricted Picard functor separated for the fpqc topology, so its canonical map to its associated sheaf is injective. If the family has Zariski-local sections, their base changes and 2.2(ii) give the matching-family equalizer on every test scheme, so the functor already is a sheaf and the map is bijective. This supplies the missing universal hypothesis for the functor assertion.','232, p. 147, corrected corollary 2.3')
event('232-2.4','targeted proof check','At the original base S the group assertions follow directly from 2.1 and 2.2: injectivity of Pic-prime(X/S) into its associated group follows from faithful-flat separatedness at S; with a section, rigidified descent makes the group coincide with Pic(X/S). No universal direct-image condition is needed for this assertion at the fixed base, in contrast to the whole-functor claim in 2.3.','232, p. 147, corollary 2.4')
event('232-2.5','independent re-proof','An automorphism of an invertible L is multiplication by a global unit on X. The direct-image hypothesis identifies it with a unit on S, and preserving the g-rigidification forces that unit to be one. Every L has a normalized rigidified representative L tensor f^*(g^*L)^(-1); representatives differing by a base line bundle give the same normalized class. By 2.1 these are exactly Pic-prime(X/S). The printed sur S is ill-typed and is corrected to sur X. The final identification with the full relative group uses the fixed-base descent argument of 2.2 and is valid under the stated extra quasi-compact separated hypotheses.','232, p. 147, remarque 2.5')
with (ROOT/'CORRECTIONS.tsv').open(newline='') as f:
    c=Counter((x['layer'],x['kind']) for x in csv.DictReader(f,delimiter='\t') if x['printed_page']=='232-147')
record_page('232',147,'Compared both French layers, entry lines 215-270, against scan leaf 6 at 400 dpi, three enlarged bands and separate crops of the Gothic sheaf letters and the final reference. Read the conclusion and proof of 2.2, corollaries 2.3-2.4 and all of remarque 2.5.\n\nRestored Gothic F/G, the wavy assignment, short arrows and tilde-over-arrow signs, wavy Picard functor names, punctuation, mixed-case underlined Remarque and the exact underlined definition spans. Removed the unprinted editorial footnote. Preserved sur S in the printed classification sentence and corrected it to sur X with the type argument. The tiny irregular fleck after the final 2.3 period is not treated as a second punctuation character.\n\nRe-proved the descent mechanism in 2.2, the group consequence 2.4 and rigidification statement 2.5. The whole-functor assertion 2.3 needs the direct-image hypothesis after arbitrary base change: the punctured real projective-line family supplies an explicit counterexample to the printed hypotheses. Added precisely that universal condition to corrected French; retained the printed wording in the diplomatic layer.\n\nOperation counts: '+'; '.join(f'{a}, {b}: {n}' for (a,b),n in sorted(c.items()))+'. Final row verdicts remain pending.')
